def get_count(self, using):
    """
    Perform a COUNT() query using the current filter constraints.
    """
    obj = self.clone()
    # Only include annotations that are referenced by filters, ordering,
    # or other annotations to avoid unnecessary joins and computations.
    for alias, annotation in list(obj.annotations.items()):
        if not self._annotation_is_referenced(alias, annotation):
            del obj.annotations[alias]
            # Decrement the refcount for any joins that were only used
            # by this annotation.
            for col in self._get_cols(annotation):
                obj.unref_alias(col.alias)
    obj.add_annotation(Count("*"), alias="__count", is_summary=True)
    return obj.get_aggregation(using, ["__count"])["__count"]

def _annotation_is_referenced(self, alias, annotation):
    """
    Return True if the annotation is referenced by filters, ordering,
    or other annotations.
    """
    # Check if the annotation is referenced in the WHERE clause.
    for child in self.where.children:
        for expr in self._get_expressions(child):
            if expr is annotation:
                return True

    # Check if the annotation is referenced in the ORDER BY clause.
    for item in self.order_by:
        if isinstance(item, str):
            name = item.lstrip("-")
            if name == alias:
                return True
        else:
            for expr in self._get_expressions(item):
                if hasattr(expr, "name") and isinstance(expr, F):
                    if expr.name == alias:
                        return True
                if hasattr(expr, "refs") and expr.refs == alias:
                    return True

    # Check if the annotation is referenced by other annotations.
    for other_alias, other_annotation in self.annotations.items():
        if other_alias == alias:
            continue
        for expr in self._get_expressions(other_annotation):
            if expr is annotation:
                return True

    return False

@staticmethod
def _get_expressions(expr):
    """Recursively yield all expressions in an expression tree."""
    yield expr
